#[inline]
pub fn lookup_pow5_div_pow2(idx: usize) -> (u128, u128, u128, u128) {
    debug_assert!(idx < LEN_POW5_DIV_POW2_LUT);
    POW5_DIV_POW2_LUT[idx]
}

